inline std::int32_t eqv(std::int32_t a, std::int32_t b) { return ~(a ^ b); }

// Comparisons: -1 / 0 / 1; GFA truth values -1 / 0.
int compare(f64 a, f64 b);
int compare(const std::string& a, const std::string& b);
inline std::int32_t truth(bool b) { return b ? -1 : 0; }
