// ---- output ------------------------------------------------------------------------------------
// PRINT: text is collected in `buf` (the pc target writes it to stdout); `col` counts characters
// since the last line feed (POS).
// `col` is POS (probe20 T1): a LF sets it to 0, a BS takes one back, every other character (also
// CR) counts. crsCol/crsLin are the cursor (CRSCOL, CRSLIN, 1-based) of the screen output; PRINT AT,
// LOCATE, HTAB, VTAB and CLS move it with ANSI sequences (ESC [ line ; column H, ESC [ H ESC [ J).
struct Output {
    std::string buf;
    int col = 0;
    int defnum = 13;
    int mode = 0;
    int crsCol = 1, crsLin = 1;
    int zone = 0;  // characters since the start of the PRINT statement: ',' pads to 16 of these (probe21)
    void begin() { zone = 0; }

    void put(const std::string& s);
    void at(f64 column, f64 line);      // PRINT AT: POS 0
    void locate(f64 column, f64 line);  // POS stays
    void htab(f64 column);
    void vtab(f64 line);
    void cls();
    std::int32_t pos() const { return col & 255; }
    void value(std::int32_t v) { put(str(flt(v), defnum)); }
    void value(f64 v) { put(str(v, defnum)); }
    void value(const std::string& s) { put(s); }
    void comma() { put(std::string(static_cast<std::size_t>(16 - zone % 16), ' ')); }  // zones of 16
    void apostrophe() { put(" "); }
    void newline() { put("\n"); }
    void tab(f64 n);
    void spc(f64 n);
};

// ---- matrices (chapter 13, D23) ----------------------------------------------------------------
// A float array as seen by MAT: the elements (first index fastest), the upper bounds, OPTION BASE.
// The matrix is the part from MAT BASE (at least OPTION BASE) to the upper bounds; a 1-D array is a
// row vector (1 x n), for MAT CPY a column vector (n x 1).
struct MatArray {
    f64* data = nullptr;
    const std::vector<std::int32_t>* upper = nullptr;
    bool dimmed = false;
};

struct MatBase {
    int mat = 1;     // MAT BASE
    int option = 0;  // OPTION BASE
};

rt_mat matView(const MatArray& a, const MatBase& b, bool column = false);
// view from the offsets (BASIC indices; none: from the start), at most n x n if n >= 0 (DET, RANG)
rt_mat matSub(const MatArray& a, const MatBase& b, const std::vector<std::int32_t>& at, std::int32_t n);
void matFill(const MatArray& a, const MatBase& b, f64 x);  // CLR, SET: the whole array, index 0 included (probe17 T3)
void matCpy(const MatArray& d, const std::vector<std::int32_t>& dAt, const MatArray& s, const std::vector<std::int32_t>& sAt,
            std::int32_t h, std::int32_t w, bool transpose, const MatBase& b);
void matPrint(Output& out, const rt_mat& m, bool format, f64 g, f64 n);  // rows, elements with ','
inline f64& matAt(const rt_mat& m, std::int32_t i, std::int32_t j) { return m.p[static_cast<long>(i) * m.rs + static_cast<long>(j) * m.cs]; }

// ---- memory (group memory, stage 1 of D6) --------------------------------------------------------
// There is no Amiga memory here: VARPTR/V: give every variable, string and array a window in an
// emulated address space; PEEK/POKE on it read and write the bytes of the value in the Amiga layout
// (big-endian, IEEE). MALLOC blocks are real bytes in that space. The addresses themselves differ
// from the Amiga (no program may rely on them), the bytes do not. An address outside every window:
// MemoryFault (not a GFA error: on the Amiga that is a crash).
struct MemoryFault {
    std::uint32_t address;
};

class Memory {
public:
    using Read = std::function<std::uint8_t(std::uint32_t)>;
    using Write = std::function<void(std::uint32_t, std::uint8_t)>;

    // code: the TYPE number of the variable (probe19 T5: # 0, % 2, ! 3, & 8, | 9), -1 none
    std::uint32_t of(std::int32_t& v, int width, int code = -1);  // %: 4, &: 2, | and !: 1 bytes
    std::uint32_t of(f64& v, int code = -1);
    std::uint32_t of(std::string& s);               // the characters (up to 32767)
    // An element of a numeric array. The window is the array block as on the original (probe19 T3):
    // the extents (upper - base + 1, long each, the last dimension first), then the elements.
    std::uint32_t of(std::vector<std::int32_t>& data, const std::vector<std::int32_t>& upper, int base,
                     const std::int32_t& element, int width);
    std::uint32_t of(std::vector<f64>& data, const std::vector<std::int32_t>& upper, int base, const f64& element);
    // Descriptors (ARRPTR, *x): a string: +0 address of the characters (0 if empty), +4 length (word);
    // an array: +0 address of its block (0 if not dimensioned), +4 dimensions (word). `key` identifies
    // the variable for SWAP *p (keyAt), code is its TYPE number.
    std::uint32_t descriptor(std::string& s);
    std::uint32_t descriptor(const void* key, int code, std::function<std::uint32_t()> block, std::function<int()> dims);
    std::int32_t typeAt(f64 address);                    // TYPE(p): the TYPE number, -1 if p is no variable
    const void* keyAt(f64 address, int& code);           // the variable of a descriptor (nullptr: none)

    std::int32_t peek(f64 address, int width);      // PEEK 0..255, DPEEK 0..65535, LPEEK signed
    void poke(f64 address, int width, f64 value);   // the lower 8/16/32 bits
    std::int32_t malloc(f64 size, f64 flags);       // MALLOC: cleared bytes, 0 if size <= 0
    std::int32_t mfree(f64 address, f64 size);     // 0, or -1 if it is no MALLOC block
    void bmove(f64 from, f64 to, f64 count);        // overlapping allowed
    // BYTE{} CARD{} INT{} LONG{} (kind B C I L), FLOAT{} SINGLE{} DOUBLE{} (F S D), CHAR{}
    std::int32_t get(f64 address, char kind);
    void set(f64 address, char kind, f64 value);
    f64 getf(f64 address, char kind);
    void setf(f64 address, char kind, f64 value);
    std::string getChars(f64 address);              // up to the zero byte
    void setChars(f64 address, const std::string& s);  // with a zero byte at the end

private:
    struct Window {
        std::uint32_t size;
        Read read;
        Write write;
        int code = -1;
        const void* key = nullptr;
    };
    std::map<std::uint32_t, Window> windows_;       // by base address
    std::map<const void*, std::uint32_t> keys_;
    std::map<std::uint32_t, std::unique_ptr<std::vector<std::uint8_t>>> blocks_;
    std::uint32_t next_ = 0x00400000;
    std::uint32_t window(const void* key, std::uint32_t size, Read read, Write write, int code = -1);
    Window& at(std::uint32_t address, std::uint32_t& offset);
    std::uint8_t get(std::uint32_t address);
    void set(std::uint32_t address, std::uint8_t b);
};

// ---- files (probe14) -----------------------------------------------------------------------------
// Sequential files on channels 0..99 (error 23 outside). Lines end with LF. Errors of the file
// system are AmigaDOS codes as on the original: 205 "object not found", 202 "object in use" (ERR
// shows them as signed bytes, -51 and -54).
constexpr int kErrObjectInUse = 202;
constexpr int kErrObjectExists = 203;
constexpr int kErrSeek = 219;
constexpr int kErrObjectNotFound = 205;

class Files {
public:
    Files() = default;
    Files(const Files&) = delete;
    Files& operator=(const Files&) = delete;
    ~Files() { closeAll(); }

    void open(const std::string& mode, f64 channel, const std::string& name, f64 recordLength = 0);
    void close(f64 channel);
    void closeAll();
    // PRINT #, WRITE #: the text goes to the channel's Output (own column); flush() writes it
    Output& output(f64 channel, const Output& screen);
    void flush(f64 channel);
    std::string lineInput(f64 channel);               // LINE INPUT #: up to the line feed
    std::string inputString(f64 channel);             // INPUT # into a string variable
    f64 inputNumber(f64 channel);                      // INPUT # into a number: error 35 if it is none
    std::string inputChars(f64 n, f64 channel);       // INPUT$(n,#c)
    std::int32_t eof(f64 channel);                    // -1 at the end
    std::int32_t lof(f64 channel);                    // length of the file
    static std::int32_t exist(const std::string& name);
    void kill(const std::string& name);
    void name(const std::string& from, const std::string& to);  // NAME a$ AS b$
    // random access (probe16): FIELD binds string variables (set to spaces of the field length);
    // GET/PUT check that they still have that length (error 54), record numbers from 1 (55)
    void field(f64 channel, const std::vector<std::string*>& vars, const std::vector<f64>& lengths);
    void get(f64 channel, bool numbered, f64 record);
    void put(f64 channel, bool numbered, f64 record);
    void record(f64 channel, f64 n);                  // RECORD #n,k: the next GET/PUT takes record k+1
    void seek(f64 channel, f64 pos);                  // beyond the end: error 219, position at the end
    void relseek(f64 channel, f64 n);
    std::int32_t loc(f64 channel);                    // byte position (0 for random files, probe16)
    std::int32_t inp(f64 channel);                    // INP(#n): one byte
    void out(f64 channel, f64 byte);                  // OUT #n,b

private:
    struct Channel {
        std::FILE* f = nullptr;
        bool input = false;     // readable
        bool output = false;    // writable
        bool writing = false;   // last access was a write (stdio needs a seek before a read)
        std::int32_t reclen = 0;  // record length of a random file (mode R), else 0
        std::int32_t next = 0;    // next record (0-based)
        std::vector<std::string*> fields;
        std::vector<std::int32_t> lengths;
        std::string name;
        Output out;
    };
    void toRead(Channel& c);
    void toWrite(Channel& c);
    std::int32_t size(Channel& c);
    std::size_t recordIndex(Channel& c, bool numbered, f64 record);
    Channel ch_[100];
    Channel& get(f64 channel, bool open);
    bool inUse(const std::string& name, const Channel* except) const;
    int peekByte(Channel& c);
    std::string item(Channel& c);
};

// ---- keyboard (docs/language.md, reference chapter 5) ---------------------------------------------
// INPUT/LINE INPUT read lines from a stream (the terminal echoes what is typed). Prompt: "text? "
// after "text";, "text" after "text",, "? " without text. Values of INPUT are separated by commas;
// missing values come from further lines (prompt "? "); a value that is not a number repeats the
// prompt and the input. INKEY$ and INPUT$(n) read characters (a line feed counts as Return, 13).
// At the end of the input: error 26.
class Keyboard {
public:
    std::istream* in = nullptr;          // nullptr: no input (the end at once)
    std::function<void()> flush;         // writes the collected output before waiting

    void begin(Output& out, const std::string& text, int mode);
    std::string field(Output& out);      // INPUT into a string variable
    f64 number(Output& out);             // INPUT into a number
    std::string line(Output& out);       // LINE INPUT
    static void end(Output& out) { out.col = 0; }  // the Return moved the cursor to the next line
    std::string inkey();                 // INKEY$: one character or ""
    std::string chars(f64 n);            // INPUT$(n)

private:
    std::string prompt_, line_;
    std::size_t pos_ = std::string::npos;  // start of the next field; npos: no field left
    bool whole_ = false;                   // line_ not yet taken (LINE INPUT)
    void read(Output& out, const std::string& prompt);
    std::string next(Output& out);
};

// WRITE: numbers as by PRINT, strings in quotes, separated by commas
void writeValue(Output& out, f64 x, bool first);
void writeValue(Output& out, const std::string& s, bool first);

// PRINT USING: one per statement.
class Using {
public:
    Using(Output& out, std::string format);
    void value(f64 x);
    void value(std::int32_t x) { value(flt(x)); }
    void value(const std::string& s);
    void end();

private:
    Output& out_;
    std::string format_;
    rt_using u_;
};

